package dev.hackuniversity.roombook.tools;

import java.time.Duration;
import java.util.List;

import org.springframework.http.ProblemDetail;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.RestClient;

/** Reads one room through the API, the way a script or another service would. */
public class ShowRoom {

    record Room(long id, String name, String building, int capacity, List<String> amenities) {
    }

    public static void main(String[] args) {
        String base = System.getenv().getOrDefault("ROOMBOOK_URL", "http://localhost:8080");
        JdkClientHttpRequestFactory requests = new JdkClientHttpRequestFactory();
        requests.setReadTimeout(Duration.ofSeconds(5)); // give up instead of waiting forever

        RestClient api = RestClient.builder().baseUrl(base).requestFactory(requests).build();
        try {
            Room room = api.get().uri("/v1/rooms/{id}", args.length > 0 ? args[0] : "1")
                    .retrieve()
                    .body(Room.class);
            System.out.printf("%s in %s seats %d: %s%n",
                    room.name(), room.building(), room.capacity(), String.join(", ", room.amenities()));
        } catch (HttpClientErrorException e) {
            // retrieve() throws on a 4xx. Roombook's errors are Problem Details, so read the title.
            ProblemDetail problem = e.getResponseBodyAs(ProblemDetail.class);
            System.out.printf("Failed: %d %s%n", problem.getStatus(), problem.getTitle());
        }
    }
}

