pm.test("signs in", () => {
  pm.response.to.have.status(200);
  const body = pm.response.json();
  pm.expect(body.tokenType).to.eql("Bearer");
  pm.environment.set("accessToken", body.accessToken);
});

pm.test("creates the booking", () => {
  pm.response.to.have.status(201);
  pm.expect(pm.response.headers.get("Location")).to.match(/^\/v1\/bookings\/\d+$/);

  const booking = pm.response.json();
  pm.expect(booking.status).to.eql("confirmed");
  pm.expect(booking.startsAt).to.eql("2026-10-05T14:00:00Z");
  pm.collectionVariables.set("bookingId", booking.id);
});

pm.test("answers in under 500 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(500);
});

